# -*- coding: utf-8 -*-
def edit(p, pairs):
    b=open(p,'rb').read(); t=b.decode('utf-8'); n=0
    for old,new in pairs:
        c=t.count(old)
        assert c==1, (p, old[:70], c)
        t=t.replace(old,new); n+=1
    open(p,'wb').write(t.encode('utf-8')); print(p, n, 'replacements')
